import { useEffect, useRef, useState, useCallback, ChangeEvent } from "react";
import {
    LineChart,
    Line,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip
} from "recharts";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type Pair = "XBT/USD" | "ETH/USD" | "SOL/USD";
type WsStatus = "connecting" | "live" | "error";
type AlertDirection = "above" | "below";

interface TradeTick {
    price: number;
    time: number;
}

interface AlertRecord {
    pair: Pair;
    price: number;
    time: number;
    threshold: number;
    direction: AlertDirection;
}

interface ChartPoint {
    time: string;
    price: number;
    ma5: number;
    ma12: number;
}

type TradesState = Partial<Record<Pair, TradeTick[]>>;
type BufferState = Partial<Record<Pair, TradeTick[]>>;
type AlertThresholds = Record<Pair, number>;
type AlertDirections = Record<Pair, AlertDirection>;

// Kraken v1 trade message shape:
// [channelId, [[price, volume, time, side, orderType, misc], ...], "trade", "ETH/USD"]
type KrakenTradeEntry = [string, string, string, string, string, string];
type KrakenTradeMessage = [number, KrakenTradeEntry[], "trade", Pair];

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const WS_URL = "wss://ws.kraken.com";

const PAIRS: Pair[] = ["XBT/USD", "ETH/USD", "SOL/USD"];

const PAIR_LABELS: Record<Pair, string> = {
    "XBT/USD": "BTC/USD",
    "ETH/USD": "ETH/USD",
    "SOL/USD": "SOL/USD",
};

const ALERT_RULES: AlertThresholds = {
    "XBT/USD": 70000,
    "ETH/USD": 4000,
    "SOL/USD": 80,
};

const ALERT_OPTIONS: Record<Pair, number[]> = {
    "XBT/USD": [35000, 40000, 45000, 50000, 55000, 60000, 65000, 70000, 75000, 80000, 85000, 90000, 95000, 100000, 105000],
    "ETH/USD": [500, 1000, 1500, 2000, 2500, 3000, 3500, 4000, 4500, 5000, 5500, 6000, 6500, 7000, 7500],
    "SOL/USD": [10, 20, 30, 40, 50, 60, 80, 90, 100, 125, 150, 175, 200, 225, 250, 275, 300, 325, 350, 375, 400, 425, 450, 475, 500],
};

const ALERT_STORAGE_KEY = "traderAlertThresholds";
const ALERT_DIRECTION_STORAGE_KEY = "traderAlertDirections";

const ALERT_DIRECTION_RULES: AlertDirections = {
    "XBT/USD": "above",
    "ETH/USD": "above",
    "SOL/USD": "above",
};

const SUBSCRIBE_MSG = JSON.stringify({
    event: "subscribe",
    pair: PAIRS,
    subscription: { name: "trade" },
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function loadThresholds(): AlertThresholds {
    try {
        const saved = JSON.parse(
            localStorage.getItem(ALERT_STORAGE_KEY) ?? "null"
        ) as Record<string, unknown> | null;
        if (!saved) return ALERT_RULES;
        // Coerce every value to a number — old Trader.js stored raw strings
        const merged: AlertThresholds = { ...ALERT_RULES };
        (Object.keys(ALERT_RULES) as Pair[]).forEach((pair) => {
            const v = Number(saved[pair]);
            if (Number.isFinite(v)) merged[pair] = v;
        });
        return merged;
    } catch {
        return ALERT_RULES;
    }
}

function loadAlertDirections(): AlertDirections {
    try {
        const saved = JSON.parse(
            localStorage.getItem(ALERT_DIRECTION_STORAGE_KEY) ?? "null"
        ) as Record<string, unknown> | null;
        if (!saved) return ALERT_DIRECTION_RULES;

        const merged: AlertDirections = { ...ALERT_DIRECTION_RULES };
        (Object.keys(ALERT_DIRECTION_RULES) as Pair[]).forEach((pair) => {
            const direction = saved[pair];
            if (direction === "above" || direction === "below") {
                merged[pair] = direction;
            }
        });
        return merged;
    } catch {
        return ALERT_DIRECTION_RULES;
    }
}

function isKrakenTradeMessage(msg: unknown): msg is KrakenTradeMessage {
    return (
        Array.isArray(msg) &&
        msg.length === 4 &&
        msg[2] === "trade" &&
        Array.isArray(msg[1])
    );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function Crypto(): JSX.Element {
    const [trades, setTrades] = useState<TradesState>({});
    const [alerts, setAlerts] = useState<AlertRecord[]>([]);
    const [wsStatus, setWsStatus] = useState<WsStatus>("connecting");
    const [alertThresholds, setAlertThresholds] = useState<AlertThresholds>(loadThresholds);
    const [alertDirections, setAlertDirections] = useState<AlertDirections>(loadAlertDirections);

    const socketRef = useRef<WebSocket | null>(null);
    const bufferRef = useRef<BufferState>({});
    const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const reconnectRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const failCountRef = useRef<number>(0);
    const alertThresholdsRef = useRef<AlertThresholds>(alertThresholds);
    const alertDirectionsRef = useRef<AlertDirections>(alertDirections);
    const lastPriceRef = useRef<Partial<Record<Pair, number>>>({});

    // Keep ref in sync and persist to localStorage whenever thresholds change
    useEffect(() => {
        alertThresholdsRef.current = alertThresholds;
        localStorage.setItem(ALERT_STORAGE_KEY, JSON.stringify(alertThresholds));
    }, [alertThresholds]);

    useEffect(() => {
        alertDirectionsRef.current = alertDirections;
        localStorage.setItem(ALERT_DIRECTION_STORAGE_KEY, JSON.stringify(alertDirections));
    }, [alertDirections]);

    const connect = useCallback((): void => {
        setWsStatus("connecting");

        let ws: WebSocket;
        try {
            ws = new WebSocket(WS_URL);
        } catch {
            setWsStatus("error");
            return;
        }
        socketRef.current = ws;

        ws.onopen = (): void => {
            failCountRef.current = 0;
            setWsStatus("live");
            ws.send(SUBSCRIBE_MSG);
        };

        ws.onmessage = (event: MessageEvent<string>): void => {
            try {
                const msg: unknown = JSON.parse(event.data);
                if (!isKrakenTradeMessage(msg)) return;

                const pair = msg[3];
                const rawTrades = msg[1];
                const now = Date.now();

                rawTrades.forEach(([price]) => {
                    const parsedPrice = parseFloat(price);
                    if (!Number.isFinite(parsedPrice)) return;

                    if (!bufferRef.current[pair]) bufferRef.current[pair] = [];
                    bufferRef.current[pair]!.push({ price: parsedPrice, time: now });

                    const previousPrice = lastPriceRef.current[pair];
                    const threshold = alertThresholdsRef.current[pair];
                    const direction = alertDirectionsRef.current[pair];
                    const crossedAbove =
                        Number.isFinite(threshold) &&
                        parsedPrice >= threshold &&
                        (previousPrice == null || previousPrice < threshold);
                    const crossedBelow =
                        Number.isFinite(threshold) &&
                        parsedPrice <= threshold &&
                        (previousPrice == null || previousPrice > threshold);

                    if ((direction === "above" && crossedAbove) || (direction === "below" && crossedBelow)) {
                        setAlerts((prev) => [
                            { pair, price: parsedPrice, time: now, threshold, direction },
                            ...prev.slice(0, 10),
                        ]);
                    }

                    lastPriceRef.current[pair] = parsedPrice;
                });
            } catch {
                // silently discard malformed frames
            }
        };

        ws.onclose = (): void => {
            failCountRef.current += 1;
            setWsStatus("connecting");
            const delay = Math.min(2000 * failCountRef.current, 10_000);
            reconnectRef.current = setTimeout(() => connect(), delay);
        };

        ws.onerror = (): void => ws.close();
    }, []);

    useEffect(() => {
        connect();
        return () => {
            if (socketRef.current) {
                socketRef.current.onclose = null;
                socketRef.current.close();
            }
            if (intervalRef.current != null) clearInterval(intervalRef.current);
            if (reconnectRef.current != null) clearTimeout(reconnectRef.current);
        };
    }, [connect]);

    // Flush buffer to state every 500 ms
    useEffect(() => {
        intervalRef.current = setInterval(() => {
            const buf = bufferRef.current;
            const keys = Object.keys(buf) as Pair[];
            if (keys.length === 0) return;

            setTrades((prev) => {
                const updated = { ...prev };
                keys.forEach((pair) => {
                    const incoming = buf[pair];
                    if (incoming && incoming.length > 0) {
                        updated[pair] = [...incoming, ...(prev[pair] ?? [])].slice(0, 50);
                        buf[pair] = [];
                    }
                });
                return updated;
            });
        }, 500);
        return () => {
            if (intervalRef.current != null) clearInterval(intervalRef.current);
        };
    }, []);

    const updateAlertThreshold = useCallback((pair: Pair, nextValue: string): void => {
        const parsed = Number(nextValue);
        if (!Number.isFinite(parsed)) return;
        setAlertThresholds((prev) => ({ ...prev, [pair]: parsed }));
    }, []);

    const updateAlertDirection = useCallback((pair: Pair, nextValue: string): void => {
        if (nextValue !== "above" && nextValue !== "below") return;
        setAlertDirections((prev) => ({ ...prev, [pair]: nextValue }));
    }, []);

    const getSeriesWithMovingAverages = useCallback(
        (pairTrades: TradeTick[] | undefined): ChartPoint[] => {
            const chronological = (pairTrades ?? []).slice().reverse();
            return chronological.map((trade, index, series) => {
                const ma5Window = series.slice(Math.max(0, index - 4), index + 1);
                const ma12Window = series.slice(Math.max(0, index - 11), index + 1);
                const ma5 = ma5Window.reduce((sum, t) => sum + t.price, 0) / ma5Window.length;
                const ma12 = ma12Window.reduce((sum, t) => sum + t.price, 0) / ma12Window.length;
                return {
                    time: new Date(trade.time).toLocaleTimeString(),
                    price: trade.price,
                    ma5,
                    ma12,
                };
            });
        },
        [],
    );

    const statusColor =
        wsStatus === "live" ? "#00c853" : wsStatus === "error" ? "#d50000" : "#aaa";

    return (
        <div className='containerDetail ml-5 mr-5 bg-lite color-lite mt--25'>
            {/* Header */}
            <div className='containerDetail flexContainer bg-tinted contentLeft'>
                <div className='p-20 size20 contentLeft color-yellow'>
                    📊 Crypto
                </div>
                <span style={{ color: statusColor, fontSize: "0.8em" }}>
                    ● {wsStatus === "live" ? "LIVE" : wsStatus === "error" ? "ERROR" : "CONNECTING…"}
                </span>
            </div>

            {/* Alerts Panel */}
            <div className='containerDetail bg-tinted p-10 mt-5 contentLeft'>
                <div className='containerDetail bg-tinted p-10 mt-5 mb-5 color-yellow size20 contentLeft'>
                    🔔 Alerts
                </div>
                <div className='containerDetail bg-tinted height-100 scroll p-10'>
                    {alerts.length === 0 ? (
                        <div>No alerts yet</div>
                    ) : (
                        alerts.map((a, i) => (
                            <div key={i} className='color-lite flexContainer contentLeft'>
                                <div className='flex8Column'>
                                    <span className='color-yellow'>{PAIR_LABELS[a.pair]}</span>{" "}
                                </div>
                                <div className='flex4Column contentRight color-green'>
                                    ${a.threshold.toFixed(2)} <span className={a.direction === "above" ? 'color-neogreen' : 'color-neored'}>{a.direction === "above" ? " > " : " < "}</span>
                                </div>
                                <div className='flex5Column contentRight color-orange pr-5'>
                                    ${a.price.toFixed(2)}
                                </div>
                                <div className='flex4Column contentLeft color-dkOrange'>
                                    {" ⏰ "}{new Date(a.time).toLocaleTimeString()}{" "}
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Asset Cards */}
            <div className='containerDetail bg-tinted mt-5 contentLeft'>
                {PAIRS.map((pair) => {
                    const pairTrades = trades[pair];
                    const data = getSeriesWithMovingAverages(pairTrades);
                    const latest = pairTrades?.[0]?.price;
                    const currentThreshold = alertThresholds[pair];
                    const currentDirection = alertDirections[pair];
                    const latestPoint: ChartPoint | undefined = data[data.length - 1];

                    const baseOptions = ALERT_OPTIONS[pair];
                    const selectOptions: number[] =
                        !baseOptions.includes(currentThreshold)
                            ? [...baseOptions, currentThreshold].sort((a, b) => a - b)
                            : baseOptions;

                    return (
                        <div
                            key={pair}
                            className='containerDetail size20 p-10 m-5 color-yellow bg-tinted contentLeft'
                        >
                            <div className='flexContainer contentLeft'>
                                <div className='flex2Column'>
                                    <h3>{PAIR_LABELS[pair]}</h3>
                                    <div className='size10 color-orange mt--20'>
                                        {latest != null
                                            ? `$${latest.toFixed(2)}`
                                            : wsStatus === "connecting"
                                            ? "Connecting…"
                                            : "Waiting for tick…"}{" "}
                                        :Current Price
                                    </div>
                                    <div className='size10 mt--10'>
                                        <div style={{ color: "#00c853" }}>
                                            {latestPoint ? `$${latestPoint.ma5.toFixed(2)}` : "—"} :MA5
                                        </div>
                                        <div style={{ color: "#42a5f5", marginTop: -10 }}>
                                            {latestPoint ? `$${latestPoint.ma12.toFixed(2)}` : "—"} :MA12
                                        </div>
                                    </div>
                                </div>
                                <div className='size10 color-lite mb-10 flex2Column contentRight'>
                                    Set Alert:
                                    <select
                                        value={currentDirection}
                                        onChange={(e: ChangeEvent<HTMLSelectElement>) =>
                                            updateAlertDirection(pair, e.target.value)
                                        }
                                        className='containerDetail p-10 ml-5 mb-5 color-yellow bg-tinted w-100'
                                    >
                                        <option value='above'>Above</option>
                                        <option value='below'>Below</option>
                                    </select>
                                    <select
                                        value={currentThreshold}
                                        onChange={(e: ChangeEvent<HTMLSelectElement>) =>
                                            updateAlertThreshold(pair, e.target.value)
                                        }
                                        className='containerDetail p-10 ml-5 color-yellow bg-tinted w-100'
                                    >
                                        {selectOptions.map((option) => (
                                            <option key={option} value={option}>
                                                ${option.toFixed(2)}
                                            </option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            <LineChart
                                width={350}
                                height={200}
                                data={data}
                                margin={{ top: 6, right: 8, left: 20, bottom: 0 }}
                            >
                                <CartesianGrid strokeDasharray="3 3" />
                                <XAxis dataKey="time" hide />
                                <YAxis
                                    domain={["auto", "auto"]}
                                    width={70}
                                    tick={{ fontSize: 10 }}
                                    tickFormatter={(value: number) => value.toFixed(1)}
                                />
                                <Tooltip />
                                <Line
                                    type="monotone"
                                    dataKey="price"
                                    dot={false}
                                    stroke="#f5b400"
                                    strokeWidth={2}
                                />
                                <Line
                                    type="monotone"
                                    dataKey="ma5"
                                    dot={false}
                                    stroke="#00c853"
                                    strokeWidth={1.5}
                                />
                                <Line
                                    type="monotone"
                                    dataKey="ma12"
                                    dot={false}
                                    stroke="#42a5f5"
                                    strokeWidth={1.5}
                                />
                            </LineChart>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}
